'use strict';
const {Pool}=require('pg');
const http=require('node:http');
const {URL}=require('node:url');
const {TenantQuotaGovernance}=require('./quota-governance');
const {JobQueue}=require('../persistence/job-queue');
const {ProviderReliability}=require('../reliability/provider-reliability');
const {ArtifactStorageService}=require('../storage/artifact-storage-service');
const {authenticate,hasRole}=require('../security/http-security');
if(process.env.DATABASE_URL){
 const pool=new Pool({connectionString:process.env.DATABASE_URL,max:Number.parseInt(process.env.PG_QUOTA_POOL_MAX||'4',10),idleTimeoutMillis:30000,connectionTimeoutMillis:5000});
 const governance=new TenantQuotaGovernance({pool});
 const installed=Symbol.for('forge.quota.governance.installed');
 if(!globalThis[installed]){
  globalThis[installed]={pool,governance};
  const originalClaimSpecific=JobQueue.prototype.claimSpecific;
  const originalEnqueue=JobQueue.prototype.enqueue,originalSucceed=JobQueue.prototype.succeed,originalFail=JobQueue.prototype.fail,originalCancel=JobQueue.prototype.cancel;
  JobQueue.prototype.enqueue=async function(options={}){
   const generatedId=options.id||require('node:crypto').randomUUID(),effectiveOptions={...options,id:generatedId,idempotencyKey:options.idempotencyKey||generatedId};
   let reservation=null;
   if(effectiveOptions.projectId){const scope=(await this.pool.query('SELECT tenant_id FROM projects WHERE id=$1',[effectiveOptions.projectId])).rows[0];if(!scope)throw Object.assign(new Error('project not found for quota admission'),{code:'TENANT_ISOLATION'});const key=`job:${effectiveOptions.idempotencyKey}`;const admission=await governance.reserve({tenantId:scope.tenant_id,projectId:effectiveOptions.projectId,dimension:'concurrent_jobs',amount:1,idempotencyKey:key,resourceType:'job',resourceId:String(generatedId),metadata:{kind:effectiveOptions.kind||'unknown'}});if(!admission.allowed)return this.get(admission.reservation.resource_id);reservation=admission.reservation}
   try{const job=await originalEnqueue.call(this,effectiveOptions);return job}catch(error){if(reservation)await governance.release({reservationId:reservation.id,reason:'job-insert-failed'}).catch(()=>{});throw error}
  };
  JobQueue.prototype.claim=async function(options={}){await this.injector.trip('db.before_transaction',{workerId:options.workerId,retryable:true});const job=await governance.fairClaim({workerId:options.workerId,kinds:options.kinds||[],leaseSeconds:this.leaseSeconds});await this.injector.trip('worker.after_claim',{jobId:job?.id,workerId:options.workerId,retryable:true});if(job?.project_id){const p=(await this.pool.query('SELECT tenant_id FROM projects WHERE id=$1',[job.project_id])).rows[0];if(p){try{await governance.reserve({tenantId:p.tenant_id,projectId:job.project_id,dimension:'concurrent_jobs',amount:1,idempotencyKey:`job:${job.idempotency_key}`,resourceType:'job',resourceId:String(job.id)})}catch(error){await this.pool.query("UPDATE forge_jobs SET status='QUEUED',worker_id=NULL,leased_until=NULL,available_at=now(),updated_at=now(),error=$1::jsonb WHERE id=$2 AND status='RUNNING'",[JSON.stringify({code:error.code||'QUOTA_EXCEEDED',message:error.message}),job.id]);throw error}}}return job};
  JobQueue.prototype.claimSpecific=async function(id,workerId,now=new Date()){const job=await originalClaimSpecific.call(this,id,workerId,now);if(job?.project_id){const p=(await this.pool.query('SELECT tenant_id FROM projects WHERE id=$1',[job.project_id])).rows[0];if(p){try{await governance.reserve({tenantId:p.tenant_id,projectId:job.project_id,dimension:'concurrent_jobs',amount:1,idempotencyKey:`job:${job.idempotency_key}`,resourceType:'job',resourceId:String(job.id)})}catch(error){await this.pool.query("UPDATE forge_jobs SET status='QUEUED',worker_id=NULL,leased_until=NULL,available_at=now(),updated_at=now(),error=$1::jsonb WHERE id=$2 AND status='RUNNING'",[JSON.stringify({code:error.code||'QUOTA_EXCEEDED',message:error.message}),job.id]);throw error}}}return job};
  async function settleJob(job,extra={}){const r=(await pool.query("SELECT id FROM forge_quota_reservations WHERE resource_type='job' AND resource_id=$1 AND status='HELD' ORDER BY created_at DESC LIMIT 1",[job.id])).rows[0];if(r)await governance.settle({reservationId:r.id,actualAmount:1,metadata:{status:job.status,...extra}}).catch(()=>{})}
  async function releaseJob(job,reason){const r=(await pool.query("SELECT id FROM forge_quota_reservations WHERE resource_type='job' AND resource_id=$1 AND status='HELD' ORDER BY created_at DESC LIMIT 1",[job.id])).rows[0];if(r)await governance.release({reservationId:r.id,reason}).catch(()=>{})}
  JobQueue.prototype.succeed=async function(id,workerId,result={},dispatchToken=null){const job=await originalSucceed.call(this,id,workerId,result,dispatchToken);if(job.project_id)await settleJob(job);return job};
  JobQueue.prototype.cancel=async function(id,workerId,reason){const job=await originalCancel.call(this,id,workerId,reason);if(job.project_id)await releaseJob(job,reason);return job};
  JobQueue.prototype.fail=async function(id,workerId,error,options={}){const job=await originalFail.call(this,id,workerId,error,options);if(job.project_id&&job.status==='FAILED')await settleJob(job,{error});return job};
  const providerInstalled=Symbol.for('forge.quota.provider.installed');
  if(!ProviderReliability.prototype[providerInstalled]){const originalExecute=ProviderReliability.prototype.execute;ProviderReliability.prototype.execute=async function(options={}){const episodeId=options.context?.episodeId||options.request?.episodeId;const scope=episodeId?(await pool.query('SELECT p.tenant_id,e.project_id FROM episodes e JOIN projects p ON p.id=e.project_id WHERE e.id=$1',[episodeId])).rows[0]:null;if(!scope)return originalExecute.call(this,options);const key=`provider:${options.context?.idempotencyKey||options.request?.idempotencyKey||`${episodeId}:${options.operation||'provider'}`}`;const admission=await governance.reserve({tenantId:scope.tenant_id,projectId:scope.project_id,dimension:'provider_executions',amount:1,idempotencyKey:key,resourceType:'provider',resourceId:key,metadata:{operation:options.operation||'provider'}});try{const result=await originalExecute.call(this,options);await governance.settle({reservationId:admission.reservation.id,actualAmount:1,metadata:{outcome:'SUCCEEDED',provider:result?.provider||null}});return result}catch(error){await governance.settle({reservationId:admission.reservation.id,actualAmount:1,metadata:{outcome:'FAILED',code:error.code||'PROVIDER_FAILED'}}).catch(()=>{});throw error}};ProviderReliability.prototype[providerInstalled]=true}
  const storageInstalled=Symbol.for('forge.quota.storage.installed');
  if(!ArtifactStorageService.prototype[storageInstalled]){const originalPut=ArtifactStorageService.prototype.putArtifact;ArtifactStorageService.prototype.putArtifact=async function(options={}){const scope=options.projectId?(await pool.query('SELECT tenant_id FROM projects WHERE id=$1',[options.projectId])).rows[0]:null;if(!scope)return originalPut.call(this,options);const artifactKey=String(options.artifactId||`artifact-${Date.now()}`);const op=await governance.reserve({tenantId:scope.tenant_id,projectId:options.projectId,dimension:'storage_operations',amount:1,idempotencyKey:`storage:${artifactKey}`,resourceType:'storage',resourceId:artifactKey,metadata:{kind:options.kind||'unknown'}});try{const result=await originalPut.call(this,options);const bytes=Number(result?.metadata?.sizeBytes||result?.sizeBytes||options.content?.length||0);await governance.settle({reservationId:op.reservation.id,actualAmount:1,metadata:{outcome:'SUCCEEDED',bytes:Number.isSafeInteger(bytes)?bytes:0}});if(Number.isSafeInteger(bytes)&&bytes>0)await governance.recordUsage({tenantId:scope.tenant_id,projectId:options.projectId,dimension:'artifact_bytes',amount:bytes,resourceType:'artifact',resourceId:String(result.id||artifactKey),metadata:{kind:options.kind||'unknown'}});return result}catch(error){await governance.release({reservationId:op.reservation.id,reason:'artifact-upload-failed'}).catch(()=>{});throw error}};ArtifactStorageService.prototype[storageInstalled]=true}
  const requestPatch=Symbol.for('forge.quota.http.installed');
  if(!http.Server.prototype[requestPatch]){const originalOn=http.Server.prototype.on;http.Server.prototype.on=function(event,listener){if(event!=='request'||typeof listener!=='function')return originalOn.call(this,event,listener);const wrapped=async(request,response)=>{const pathname=new URL(request.url||'/','http://localhost').pathname;if(pathname.startsWith('/internal/governance/'))return handleOperatorRequest(request,response,pathname);const admission=await governance.httpAdmission({request});if(!admission.allowed){response.statusCode=admission.statusCode||429;response.setHeader('content-type','application/json; charset=utf-8');if(admission.retryAfter)response.setHeader('retry-after',String(admission.retryAfter));return response.end(JSON.stringify({error:{code:admission.code||'RATE_LIMITED',message:admission.message||'Tenant admission rejected'}}))}if(admission.remaining!==undefined)response.setHeader('x-forge-quota-remaining',String(admission.remaining));return listener(request,response)};return originalOn.call(this,event,wrapped)};http.Server.prototype[requestPatch]=true}
  async function readJson(request){return new Promise((resolve,reject)=>{let size=0;const chunks=[];request.on('data',chunk=>{size+=chunk.length;if(size>1024*1024){reject(Object.assign(new Error('request body too large'),{statusCode:413}));request.destroy();return}chunks.push(chunk)});request.on('end',()=>{try{resolve(chunks.length?JSON.parse(Buffer.concat(chunks).toString('utf8')):{})}catch(e){reject(Object.assign(new Error('invalid JSON'),{statusCode:400}))}});request.on('error',reject)})}
  async function operatorAuth(request,response){const auth=authenticate(request,{apiToken:process.env.API_BEARER_TOKEN||null,authSecret:process.env.FORGE_AUTH_SIGNING_SECRET||null,staticActor:process.env.FORGE_STATIC_ACTOR_ID||null,staticTenant:process.env.FORGE_STATIC_TENANT_ID||null});if(!auth||!hasRole(auth,'OWNER')){response.statusCode=403;response.setHeader('content-type','application/json');response.end(JSON.stringify({error:{code:'FORBIDDEN'}}));return null}return auth}
  async function handleOperatorRequest(request,response,pathname){const auth=await operatorAuth(request,response);if(!auth)return;try{if(pathname==='/internal/governance/diagnostics'&&request.method==='GET'){const d=await governance.diagnostics();response.statusCode=200;response.setHeader('content-type','application/json');return response.end(JSON.stringify(d))}if(pathname==='/internal/governance/policy'&&request.method==='GET'){const u=new URL(request.url,'http://localhost'),tenantId=u.searchParams.get('tenantId')||auth.tenantId,projectId=u.searchParams.get('projectId')||null;if(tenantId!==auth.tenantId){response.statusCode=403;return response.end(JSON.stringify({error:{code:'TENANT_ISOLATION'}}))}const p=await governance.effectivePolicy(tenantId,projectId);response.statusCode=200;response.setHeader('content-type','application/json');return response.end(JSON.stringify({policy:p,effectiveAt:new Date().toISOString()}))}if(pathname==='/internal/governance/policy'&&request.method==='PUT'){const body=await readJson(request);if(body.tenantId&&body.tenantId!==auth.tenantId)throw Object.assign(new Error('tenant isolation violation'),{code:'TENANT_ISOLATION',statusCode:403});const row=await governance.configurePolicy({tenantId:auth.tenantId,projectId:body.projectId||null,policy:body.policy||{},actor:auth.actor,requestId:request.headers['x-request-id']||null});response.statusCode=200;response.setHeader('content-type','application/json');return response.end(JSON.stringify({policy:row,effectivePolicy:await governance.effectivePolicy(auth.tenantId,body.projectId||null)}))}if(pathname==='/internal/governance/dry-run'&&request.method==='POST'){const body=await readJson(request);const tenantId=body.tenantId||auth.tenantId;if(tenantId!==auth.tenantId)throw Object.assign(new Error('tenant isolation violation'),{code:'TENANT_ISOLATION',statusCode:403});const p=await governance.effectivePolicy(tenantId,body.projectId||null);const dimension=body.dimension;if(!['concurrent_jobs','provider_executions','artifact_bytes','storage_operations','runner_executions','cpu_ms','wall_time_ms'].includes(dimension))throw Object.assign(new Error('invalid dimension'),{statusCode:400});const amount=Number(body.amount||1);if(!Number.isSafeInteger(amount)||amount<1)throw Object.assign(new Error('amount must be a positive safe integer'),{statusCode:400});const preview=await governance.currentUsageInTx({query:(...args)=>pool.query(...args)},tenantId,body.projectId||null,dimension,Number(p.reset_interval_seconds));response.statusCode=200;response.setHeader('content-type','application/json');return response.end(JSON.stringify({dryRun:true,policy:p,dimension,amount,currentUsage:preview,projectedUsage:preview+amount,allowed:preview+amount<=Number(p[dimension])}))}response.statusCode=404;response.setHeader('content-type','application/json');return response.end(JSON.stringify({error:{code:'NOT_FOUND'}}))}catch(error){response.statusCode=error.statusCode||500;response.setHeader('content-type','application/json');return response.end(JSON.stringify({error:{code:error.code||'INTERNAL_ERROR',message:error.message}}))}}
 }
}
module.exports=globalThis[Symbol.for('forge.quota.governance.installed')]||null;
